/* Career-owned targets. Ratings and transactions reuse existing game systems. */
let watchView='All Targets',watchSearch='',watchBrowse=false,watchCompare=[],watchRoster=null,watchBusy=false;
const WATCH_VIEWS=['All Targets','Draft Prospects','Free Agents','Trade Block'];
function watchStore(){return state.watchList??={targets:[]}}
function watchUniverse(){return [...state.teams.flatMap(t=>t.roster.map(p=>({p,t,kind:'player'}))),...state.free.map(p=>({p,t:null,kind:'free'})),...(state.draft?.year===state.year?state.draft.prospects:[]).map(p=>({p,t:null,kind:'draft'})),...(state.draftRights||[]).map(r=>({p:r.player,t:state.teams[r.team],kind:'rights'}))]}
function watchFind(id){return watchUniverse().find(r=>r.p.id===id)}
function watchEntry(id){return watchStore().targets.find(e=>e.id===id)}
function watchSnapshot(r){return {injured:injuryDays(r.p)>0,contract:r.kind+':'+(r.t?.id??'FA')+':'+(r.p.contractThrough??state.year)+':'+r.p.salary,refuses:!!negotiationStatus(r.p).refuses,year:state.year,gp:r.p.gp||0,cold:false}}
async function watchCommit(action){if(watchBusy||!ownerCanManage())return;const before=copy(state);watchBusy=true;try{action();if(await save()===false)throw Error();}catch{state=before;toast('Watch list could not be saved. Please try again.')}finally{watchBusy=false;render();if(document.getElementById('profile').open&&activePlayerId&&playerContext(activePlayerId))renderPlayerProfile()}}
function watchToggle(id){const r=watchFind(id);if(!r)return;return watchCommit(()=>{const w=watchStore();if(watchEntry(id)){w.targets=w.targets.filter(e=>e.id!==id);watchCompare=watchCompare.filter(x=>x!==id)}else{if(w.targets.length>=300)return toast('Your watch list is full (300 targets).');w.targets.push({id,name:r.p.name,note:'',alerts:{injury:true,stats:true,contract:true},scouting:0,due:null,snapshot:watchSnapshot(r),seen:[]})}})}
function watchEdit(id,key,value){return watchCommit(()=>{const e=watchEntry(id);if(!e)return;if(key==='note')e.note=String(value).slice(0,300);else if(['injury','stats','contract'].includes(key))e.alerts[key]=!!value})}
function watchChangeView(v){if(!WATCH_VIEWS.includes(v))return;if(v==='Draft Prospects')ensureDraft();watchView=v;render()}
function watchScout(id){const r=watchFind(id),e=watchEntry(id);if(!r||r.kind!=='draft'||!e)return;return watchCommit(()=>{if(e.scouting>=100||e.due!==null)return;e.due=medicalStamp()+3;toast('Scout assigned: report due in 3 league days.')})}
function watchPotential(r){const e=watchEntry(r.p.id);if(r.kind!=='draft')return String(r.p.pot);const s=financeScoutedPotential(r.p),completion=e?.scouting||0,range=Math.ceil(s.range*(1-completion/100)),estimate=Math.round(s.estimate+(r.p.pot-s.estimate)*completion/100);return range?estimate+' ± '+range:String(r.p.pot)}
function watchRound(r){if(r.kind!=='draft')return '—';const order=[...state.draft.prospects].sort((a,b)=>draftScore(b,team())-draftScore(a,team())||a.id-b.id),round=Math.floor(order.findIndex(p=>p.id===r.p.id)/state.teams.length)+1;return round<=draftRoundCount()?String(round):'Undrafted'}
function watchInterest(r){if(r.kind==='draft'||r.kind==='rights')return {label:'Not eligible',icon:'—'};if(r.t?.id===controlledTeamId())return {label:'On your roster',icon:'●'};const e=faEntry(r.p.id);if(r.kind==='free'&&faActive()&&e){const interest=faInterest(r.p,team(),{salary:e.demand,minutes:24});return {label:interest.score>=80?'Highly interested':interest.score>=60?'Open to an offer':'Low interest',icon:interest.score>=80?'🟢':interest.score>=60?'🟡':'🔴',detail:interest.feedback+' · at asking salary and 24 minutes'}}return {label:r.t?'Under contract':'Not yet assessed',icon:'—'}}
function watchAsk(r){return r.kind==='draft'?'Rookie scale':r.kind==='free'?money(faEntry(r.p.id)?.demand??freeAgentQuote(r.p)):money(r.p.salary)}
function watchContract(r){return r.kind==='draft'?'Draft '+state.year:r.kind==='free'?'Unsigned':r.kind==='rights'?'Draft rights':Math.max(1,(r.p.contractThrough??state.year)-state.year+1)+' yr'+((r.p.contractThrough??state.year)<=state.year?' · Expiring':'')}
function watchValue(r){return Math.round(Math.max(1,Math.min(100,tradePlayerValue(r.p,team()))))}
function watchOpen(id){const r=watchFind(id);if(!r)return;if(r.kind==='draft')return draftReport(id);if(r.kind==='rights')return toast('This player is held under draft rights. See Draft → Your picks.');openPlayerProfile(id)}
function watchTrade(id){const r=watchFind(id);if(r?.kind!=='player'||!r.t||r.t.id===controlledTeamId())return;playerTradeAction(id)}
function watchOffer(id){const r=watchFind(id);if(r?.kind!=='free')return;if(faActive())return faOfferDialog(id);titleModal('Offer contract',`<p>${escapeHTML(r.p.name)} · Asking ${money(r.p.salary)} / year</p><p>Regular-season signing uses the current asking salary and the existing roster and payroll rules.</p><div class="actions"><button onclick="closeTitleModal()">Cancel</button><button class="primary" onclick="watchSign(${id})">Offer contract</button></div>`)}
function watchSign(id){if(!ownerCanManage()||!state.free.some(p=>p.id===id))return;closeTitleModal();sign(id);render()}
function watchSelect(id,checked){if(checked&&!watchCompare.includes(id)){if(watchCompare.length>=3){toast('Compare up to three targets.');render();return}watchCompare.push(id)}else if(!checked)watchCompare=watchCompare.filter(x=>x!==id);render()}
function watchMetrics(){return new Map(statsRows(statsEntries('all','all','regular')).map(r=>[r.id,r]))}
function watchStat(r,m,key){const s=m.get(r.p.id);return s?.gp&&Number.isFinite(s[key])?(key==='per'?s[key]:s[key]/s.gp).toFixed(1):'—'}
function watchComparison(m){const targets=watchCompare.map(watchFind).filter(Boolean);if(!targets.length)return '';const own=team().roster.find(p=>p.id===Number(watchRoster))||team().roster[0];if(!own)return '';const rows=[{p:own,t:team(),kind:'player'},...targets],fields=[['Age',r=>r.p.age],['Position',r=>r.p.pos],['OVR',r=>r.p.ovr],['POT',watchPotential],['PPG',r=>watchStat(r,m,'pts')],['RPG',r=>watchStat(r,m,'reb')],['APG',r=>watchStat(r,m,'ast')],['PER*',r=>watchStat(r,m,'per')],['Salary / ask',watchAsk],['Contract',watchContract],['Trade value / 100',watchValue]];return `<section class="panel watch-compare"><div class="panelhead"><h2>Player comparison</h2><label>Your player<select onchange="watchRoster=Number(this.value);render()">${team().roster.map(p=>`<option value="${p.id}" ${p.id===own.id?'selected':''}>${escapeHTML(p.name)}</option>`).join('')}</select></label><button onclick="watchCompare=[];render()">Clear comparison</button></div><div class="tablewrap"><table><thead><tr><th>Metric</th>${rows.map(r=>`<th>${escapeHTML(r.p.name)}</th>`).join('')}</tr></thead><tbody>${fields.map(([label,value])=>`<tr><th>${label}</th>${rows.map(r=>`<td>${escapeHTML(String(value(r)))}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`}
function watchListView(){const w=watchStore(),blocks=new Set(tradeBlockLeagueAssets().filter(r=>r.p).map(r=>r.p.id)),m=watchMetrics();let rows=watchUniverse().filter(r=>watchBrowse?!watchEntry(r.p.id):!!watchEntry(r.p.id));rows=rows.filter(r=>(watchView==='All Targets'||watchView==='Draft Prospects'&&r.kind==='draft'||watchView==='Free Agents'&&(r.kind==='free'||r.kind==='player'&&(r.p.contractThrough??state.year)<=state.year)||watchView==='Trade Block'&&blocks.has(r.p.id))&&[r.p.name,r.p.pos,r.t?.city||r.kind,watchEntry(r.p.id)?.note||''].join(' ').toLowerCase().includes(watchSearch.toLowerCase()));const count=rows.length;rows=rows.slice(0,100);return `<section class="panel watch-list"><div class="panelhead"><div><h2>${watchBrowse?'Find targets':'Watch List'}</h2><p>${w.targets.length} saved targets · ${count} matching ${watchBrowse?'players':'targets'}</p></div><button class="primary" onclick="watchBrowse=!watchBrowse;render()">${watchBrowse?'Back to saved targets':'Add targets'}</button></div><nav class="po-tabs" aria-label="Watch list views">${WATCH_VIEWS.map(v=>`<button class="${v===watchView?'selected':''}" aria-pressed="${v===watchView}" onclick="watchChangeView('${v}')">${v}</button>`).join('')}</nav><div class="watch-tools"><label>Search players, positions, teams or notes<input value="${escapeHTML(watchSearch)}" placeholder="Name, team, 3&D Target…" onchange="watchSearch=this.value;render()"></label><p>Compare up to 3 targets against one roster player. Scouting reports take 3 league days and add 25% completion per assignment.</p></div><div class="tablewrap"><table><thead><tr><th>Compare</th><th>Player</th><th>Age</th><th>Pos</th><th>Team</th><th>OVR</th><th>POT</th><th>PPG</th><th>RPG</th><th>APG</th><th>PER*</th><th>Salary / ask</th><th>Contract</th><th>Value / 100</th><th>Interest</th><th>Projected round</th><th>Scouted</th><th>Alerts &amp; notes</th><th>Actions</th></tr></thead><tbody>${rows.map(r=>{const {p}=r,e=watchEntry(p.id),interest=watchInterest(r);return `<tr><td>${e?`<input type="checkbox" aria-label="Compare ${escapeHTML(p.name)}" ${watchCompare.includes(p.id)?'checked':''} onchange="watchSelect(${p.id},this.checked)">`:'—'}</td><td><button class="namebutton" onclick="watchOpen(${p.id})">${escapeHTML(p.name)}</button></td><td>${p.age}</td><td>${p.pos}</td><td>${escapeHTML(r.kind==='draft'?'Draft':r.t?.abbr||'FA')}</td><td>${ratingMarkup(p.ovr)}</td><td>${r.kind==='draft'?watchPotential(r):ratingMarkup(p.pot)}</td>${['pts','reb','ast','per'].map(k=>`<td>${watchStat(r,m,k)}</td>`).join('')}<td>${watchAsk(r)}</td><td>${watchContract(r)}</td><td>${watchValue(r)}</td><td title="${escapeHTML(interest.detail||interest.label)}">${interest.icon} ${interest.label}</td><td>${watchRound(r)}</td><td>${r.kind==='draft'?(e?.scouting||0)+'%'+(e?.due!==null&&e?.due!==undefined?' · '+Math.max(0,e.due-medicalStamp())+' days remaining':''):'—'}</td><td>${e?`<div class="watch-alerts">${[['injury','Injury / recovery'],['stats','Stat milestones'],['contract','Contract updates']].map(([key,label])=>`<label><input type="checkbox" ${e.alerts[key]?'checked':''} onchange="watchEdit(${p.id},'${key}',this.checked)">${label}</label>`).join('')}<label>Tags / notes<textarea maxlength="300" aria-label="Notes for ${escapeHTML(p.name)}" placeholder="3&D Target, Future Core…" onchange="watchEdit(${p.id},'note',this.value)">${escapeHTML(e.note)}</textarea></label></div>`:'Add to track alerts and notes'}</td><td><div class="watch-actions">${e?`${r.kind==='draft'?`<button onclick="watchScout(${p.id})" ${e.scouting>=100||e.due!==null?'disabled':''}>Assign scout</button>`:r.kind==='free'?`<button onclick="watchOffer(${p.id})">Offer contract</button>`:r.kind==='player'&&r.t.id!==controlledTeamId()?`<button onclick="watchTrade(${p.id})">Propose trade</button>`:''}<button onclick="watchToggle(${p.id})">Remove</button>`:`<button onclick="watchToggle(${p.id})">Watch player</button>`}</div></td></tr>`}).join('')||'<tr><td colspan="19">No matching targets. Use Add targets to browse players or choose another view.</td></tr>'}</tbody></table></div><p class="note">${count>100?'Showing the first 100 results. Narrow your search. ':''}Stats use recorded regular-season games. PER* is the existing game-model estimate. Trade value is your team’s valuation, capped at 100, not a guaranteed offer. Prospect game statistics are unavailable until recorded. Signing interest is assessed during active free agency at asking salary and a 24-minute role.</p>${!watchBrowse?w.targets.filter(e=>!watchFind(e.id)).map(e=>`<p class="note">${escapeHTML(e.name)} · No longer in the active player pool. Notes: ${escapeHTML(e.note)} <button onclick="watchRemoveMissing(${e.id})">Remove</button></p>`).join(''):''}</section>${watchComparison(m)}`}
function watchRemoveMissing(id){return watchCommit(()=>{watchStore().targets=watchStore().targets.filter(e=>e.id!==id);watchCompare=watchCompare.filter(x=>x!==id)})}
function watchNotify(e,key,subject,body){if(e.seen.includes(key))return;e.seen.push(key);e.seen=e.seen.slice(-100);addGMMessage('Watch list','Scouting department',subject,body)}
function watchProcess(){if(!state.watchList)return;const byId=new Map(watchUniverse().map(r=>[r.p.id,r]));for(const e of watchStore().targets){const r=byId.get(e.id);if(!r)continue;const next=watchSnapshot(r),old=e.snapshot;if(e.due!==null&&medicalStamp()>=e.due){e.scouting=Math.min(100,e.scouting+25);e.due=null;watchNotify(e,'scout:'+state.year+':'+e.scouting,'Scouting report: '+r.p.name,'Scouting completion is now '+e.scouting+'%. Updated potential estimate: '+watchPotential(r)+'.')}if(old){if(e.alerts.injury&&old.injured!==next.injured)watchNotify(e,'injury:'+state.year+':'+state.day+':'+next.injured,(next.injured?'Injury: ':'Recovered: ')+r.p.name,next.injured?r.p.name+' is injured: '+(r.p.medicalInfo?.name||'injury')+'. Expected recovery: '+injuryDays(r.p)+' days.':r.p.name+' is available again.');if(e.alerts.contract&&old.contract!==next.contract)watchNotify(e,'contract:'+state.year+':'+state.day+':'+next.contract,'Contract update: '+r.p.name,r.p.name+' · '+watchContract(r)+' · '+watchAsk(r)+' · '+(r.t?.city||'Free agency'));if(e.alerts.contract&&!old.refuses&&next.refuses)watchNotify(e,'refuses:'+state.year+':'+state.day,'Negotiations unavailable: '+r.p.name,r.p.name+' is currently refusing extension discussions due to morale.');if(e.alerts.stats&&(old.year!==state.year||old.gp!==next.gp)){const games=state.history.flatMap((g,i)=>g.box.filter(b=>b.playerId===e.id&&b.played!==false).map(b=>({...b,key:state.year+':'+i})));for(const g of games.slice(-(old.year===state.year?Math.max(0,next.gp-old.gp):next.gp)))if(g.pts>=40)watchNotify(e,'40:'+g.key,'40-point game: '+r.p.name,r.p.name+' scored '+g.pts+' points in a recorded game.');const recent=games.slice(-3),cold=recent.length===3&&recent.every(g=>g.fga>=5&&g.fgm/g.fga<.3);if(cold&&!old.cold)watchNotify(e,'cold:'+recent[2].key,'Cold streak: '+r.p.name,r.p.name+' shot below 30% in three consecutive games (at least five attempts each).');next.cold=cold;}else next.cold=old.cold;}e.snapshot=next}}
const watchSaveBefore=save;save=function(...args){watchProcess();return watchSaveBefore(...args)};
const watchDayBefore=ownerDay;ownerDay=function(...args){const result=watchDayBefore(...args);watchProcess();return result};
const watchProfileBefore=renderPlayerProfile;renderPlayerProfile=function(){watchProfileBefore();const d=document.getElementById('profile'),footer=d.querySelector?.('.pp-actions');if(footer&&playerContext(activePlayerId)){const button=document.createElement('button');button.type='button';button.textContent=watchEntry(activePlayerId)?'Remove from watch list':'Watch player';button.onclick=()=>watchToggle(activePlayerId);footer.appendChild(button)}};
const watchReportBefore=draftReport;draftReport=function(id){watchReportBefore(id);const d=document.getElementById('profile'),content=d.querySelector?.('.pp-content');if(content){const button=document.createElement('button');button.textContent=watchEntry(id)?'Remove from watch list':'Watch prospect';button.onclick=async()=>{await watchToggle(id);d.close();draftReport(id)};content.prepend(button)}};
const watchValidateBefore=validateCareerData;validateCareerData=function(raw){const result=watchValidateBefore(raw);if(raw.watchList!==undefined){const w=raw.watchList,ids=new Set();if(!w||!Array.isArray(w.targets)||w.targets.length>300)throw Error('Invalid watch list');result.watchList={targets:w.targets.map(e=>{if(!e||!Number.isInteger(e.id)||e.id<0||e.id>10000000||ids.has(e.id)||typeof e.name!=='string'||e.name.length>80||typeof e.note!=='string'||e.note.length>300||!e.alerts||['injury','stats','contract'].some(k=>typeof e.alerts[k]!=='boolean')||![0,25,50,75,100].includes(e.scouting)||!(e.due===null||Number.isInteger(e.due)&&Math.abs(e.due)<4000000)||!Array.isArray(e.seen)||e.seen.length>100||e.seen.some(k=>typeof k!=='string'||k.length>150))throw Error('Invalid watch target');ids.add(e.id);const s=e.snapshot;if(s&&(['injured','refuses','cold'].some(k=>typeof s[k]!=='boolean')||typeof s.contract!=='string'||s.contract.length>150||!Number.isInteger(s.year)||!Number.isInteger(s.gp)||s.gp<0))throw Error('Invalid watch snapshot');return {id:e.id,name:e.name,note:e.note,alerts:{...e.alerts},scouting:e.scouting,due:e.due,seen:[...e.seen],snapshot:s?{injured:s.injured,refuses:s.refuses,cold:s.cold,contract:s.contract,year:s.year,gp:s.gp}:null}})}}return result};
/* Only report actual attempted negotiations as breakdowns. */
const watchExtendBefore=extendPlayerContract;extendPlayerContract=function(id){const c=playerContext(id),e=watchEntry(id);if(c?.own&&e?.alerts.contract&&negotiationStatus(c.p).refuses){watchNotify(e,'extension:'+state.year+':'+state.day,'Extension talks broke down: '+c.p.name,c.p.name+' refused your request to negotiate an extension.');save()}return watchExtendBefore(id)};
const watchFALogBefore=faLog;faLog=function(text){watchFALogBefore(text);for(const e of state.watchList?.targets||[]){const r=watchFind(e.id);if(r&&e.alerts.contract&&text.startsWith(r.p.name+' declined:'))watchNotify(e,'declined:'+state.year+':'+state.freeAgency.phase+':'+state.freeAgency.round,'Contract offer declined: '+r.p.name,text)}};
